from collections import deque

def find_holes(pattern):
    h, w = len(pattern), len(pattern[0])
    visited = [[False]*w for _ in range(h)]

    # BFS from edges to mark everything connected to edge
    queue = deque()
    for c in range(w):
        if not visited[0][c]:
            queue.append((0,c))
        if not visited[h-1][c]:
            queue.append((h-1,c))
    for r in range(1,h):
        if not visited[r][0]:
            queue.append((r,0))
        if not visited[r][w-1]:
            queue.append((r,w-1))

    while queue:
        r, c = queue.popleft()
        if not visited[r][c]:
            visited[r][c] = True
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < h and 0 <= nc < w and not visited[nr][nc]:
                    queue.append((nr, nc))

    # Holes are unvisited B cells
    holes = [(r,c) for r in range(h) for c in range(w) 
             if pattern[r][c] == 'B' and not visited[r][c]]
    return holes

