from collections import deque

def find_components(pattern):
    h, w = len(pattern), len(pattern[0])
    visited = [[False]*w for _ in range(h)]
    components = []

    for r in range(h):
        for c in range(w):
            if pattern[r][c] == '#' and not visited[r][c]:
                # Found new component
