from collections import deque

def find_enclosed_regions(pattern, target_value):
    """Find regions of target_value that are completely enclosed by non-target"""
    h, w = len(pattern), len(pattern[0])
    visited = [[False]*w for _ in range(h)]

    # Start BFS from edges
    queue = deque()
    for r in range(h):
        for c in range(w):
            if r == 0 or r == h-1 or c == 0 or c == w-1:
                if pattern[r][c] != target_value:
                    queue.append((r,c))
                    visited[r][c] = True

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < h and 0 <= nc < w:
                if not visited[nr][nc] and pattern[nr][nc] != target_value:
                    visited[nr][nc] = True
                    queue.append((nr, nc))

    # Find connected components of target value that aren't marked as reachable from edge
    enclosures = []
    component_visited = set()

    for r in range(h):
        for c in range(w):
            if pattern[r][c] == target_value and (r,c) not in visited and (r,c) not in component_visited:
                # Found new component
                comp = [(r,c)]
                q = deque([(r,c)])
                while q:
                    cr, cc = q.popleft()
                    component_visited.add((cr, cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < h and 0 <= nc < w:
                            if (nr, nc) not in visited and pattern[nr][nc] == target_value and (nr, nc) not in component_visited:
                                comp.append((nr, nc))
                                q.append((nr, nc))
                enclosures.append(comp)

    return enclosures

