def count_isolated_by_value(pattern, target_val):
    h, w = len(pattern), len(pattern[0])
    isolated = 0

    visited_global = set()

    for r in range(h):
        for c in range(w):
            if pattern[r][c] == target_val and (r,c) not in visited_global:
                # Found a new group
                q = [(r,c)]
                visited_group = {(r,c)}
                while q:
                    cr, cc = q.pop(0)
                    visited_global.add((cr, cc))
                    has_neighbor = False
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < h and 0 <= nc < w:
                            if pattern[nr][nc] == target_val and (nr, nc) not in visited_group:
