def has_neighbors_with_top_colors(pattern_section, r, c, num_rows_above):
    """Check if cell at (r,c) has orthogonal neighbors that match colors from top section"""
    h, w = len(pattern_section), len(pattern_section[0])

    # Get top section colors (excluding separator row)
    top_colors = set()
    for rr in range(num_rows_above):
        for cc in range(w):
            if pattern_section[rr][cc] not in [1]:  # Exclude separator
                top_colors.add(pattern_section[rr][cc])

    # Check immediate vertical neighbors in top section
    neighbor_colors = set()
    for dr in [-1, 0, 1]:
        nr = r + dr
        if 0 <= nr < num_rows_above:
            neighbor_colors.add(pattern_section[nr][c])

    # Also check horizontal neighbors
    for dc in [-1, 1]:
        nc = c + dc
        if 0 <= nc < w:
            if pattern_section[r][nc] != 1:
                neighbor_colors.add(pattern_section[r][nc])

    # For cells near top boundary
    return top_colors and not neighbor_colors.isdisjoint(top_colors)

